#[inline]
pub unsafe fn xmlCharStrdup(mut cur: *const c_char) -> *mut xmlChar {
    if cur.is_null() {
        return ::core::ptr::null_mut::<xmlChar>();
    }
    let len = libc::strlen(cur) as c_long as c_int;
    xmlCharStrndup(cur, len)
}

